import { rename, writeFile } from 'node:fs/promises';
import { relative, resolve } from 'node:path';

import { z } from 'zod';

import {
  enrichmentFromModelsDev,
  fromModelsDev,
  fromOpenRouter,
  INDEX_PROVIDERS,
  MAX_INT32,
  ModelIndexCatalog,
  MODELS_DEV_PROVIDERS,
  type IndexedModel,
  type ModelsDevEnrichment,
  type OpenRouterModelInput,
} from '../src/index';

const SNAPSHOT_PATH = resolve(
  import.meta.dirname,
  '../src/catalog/model-index.snapshot.ts'
);
const SNAPSHOT_HEADER =
  '// Generated by scripts/refresh-snapshot.ts from models.dev and OpenRouter /api/v1/models.';

const MODELS_DEV_URL = 'https://models.dev/api.json';
const OPENROUTER_MODELS_URL = 'https://openrouter.ai/api/v1/models';
const OPENROUTER_ORIGIN = new URL(OPENROUTER_MODELS_URL).origin;
const OPENROUTER_SECTION = 'openrouter';
const REQUEST_TIMEOUT_MS = 15_000;
const MAX_MODEL_PAGES = 20;
const MS_PER_SECOND = 1_000;
const MS_PER_DAY = 86_400_000;
// OpenRouter marks perpetual models with a far-future date (2098-12-31) instead of null.
const EXPIRATION_SENTINEL_HORIZON_MS = 10 * 365 * MS_PER_DAY;
const REASONING_EFFORTS: readonly string[] = [
  'low',
  'medium',
  'high',
  'xhigh',
  'max',
];
const UNPARSEABLE_MODEL_ID = '<unparseable>';

interface ModelsDevRead {
  readonly models: readonly IndexedModel[];
  readonly enrichment: ReadonlyMap<string, ModelsDevEnrichment>;
  readonly discarded: readonly string[];
}

interface OpenRouterRead {
  readonly models: readonly OpenRouterModelInput[];
  readonly complete: boolean;
  readonly discarded: readonly string[];
}

const modelIdSchema = z.object({ id: z.string() });

const providerSectionSchema = z
  .object({ models: z.record(z.string(), z.unknown()) })
  .optional();

const costPerTokenSchema = z
  .string()
  .refine((raw) => raw.trim().length > 0)
  .transform(Number)
  .refine((cost) => Number.isFinite(cost) && cost >= 0);

const optionalCostPerTokenSchema = costPerTokenSchema.nullish().catch(null);

const openRouterModelSchema = z.object({
  id: z.string().min(1),
  name: z.string().min(1),
  created: z.number().int().nonnegative(),
  context_length: z.number().int().positive().max(MAX_INT32),
  architecture: z
    .object({
      input_modalities: z.array(z.string()).nullish(),
      output_modalities: z.array(z.string()).nullish(),
    })
    .nullish(),
  pricing: z.object({
    prompt: costPerTokenSchema,
    completion: costPerTokenSchema,
    input_cache_read: optionalCostPerTokenSchema,
    input_cache_write: optionalCostPerTokenSchema,
  }),
  supported_parameters: z.array(z.string()).nullish(),
  top_provider: z
    .object({
      max_completion_tokens: z
        .number()
        .int()
        .positive()
        .max(MAX_INT32)
        .nullish(),
    })
    .nullish(),
  expiration_date: z.string().nullish(),
  reasoning: z
    .object({
      supported_efforts: z.array(z.string()).nullish(),
      mandatory: z.boolean().nullish(),
    })
    .nullish(),
});

const openRouterPageSchema = z.object({
  data: z.array(z.unknown()),
  links: z.object({ next: z.string().nullish() }).nullish(),
});

type OpenRouterModel = z.infer<typeof openRouterModelSchema>;

function upstreamIdOf(raw: unknown): string {
  const parsed = modelIdSchema.safeParse(raw);
  return parsed.success ? parsed.data.id : UNPARSEABLE_MODEL_ID;
}

async function getJson(url: string, source: string): Promise<unknown> {
  const response = await fetch(url, {
    signal: AbortSignal.timeout(REQUEST_TIMEOUT_MS),
  });
  if (!response.ok) {
    throw new Error(`${source} request failed: HTTP ${response.status}`);
  }
  return response.json();
}

function entriesOf(section: z.infer<typeof providerSectionSchema>): unknown[] {
  return section === undefined ? [] : Object.values(section.models);
}

async function readModelsDev(): Promise<ModelsDevRead> {
  const payload = z
    .record(z.string(), z.unknown())
    .parse(await getJson(MODELS_DEV_URL, 'models.dev'));

  const models: IndexedModel[] = [];
  const discarded: string[] = [];
  for (const provider of MODELS_DEV_PROVIDERS) {
    for (const entry of entriesOf(
      providerSectionSchema.parse(payload[provider])
    )) {
      const model = fromModelsDev(provider, entry);
      if (model === null) {
        discarded.push(`${provider}:${upstreamIdOf(entry)}`);
      } else {
        models.push(model);
      }
    }
  }

  const enrichment = new Map<string, ModelsDevEnrichment>();
  const section = providerSectionSchema.safeParse(payload[OPENROUTER_SECTION]);
  if (!section.success) {
    console.warn('models.dev openrouter section is unreadable; no enrichment');
    return { models, enrichment, discarded };
  }
  for (const entry of entriesOf(section.data)) {
    const facts = enrichmentFromModelsDev(entry);
    if (facts !== null) {
      enrichment.set(upstreamIdOf(entry), facts);
    }
  }
  return { models, enrichment, discarded };
}

function toExpirationDate(raw: string | null | undefined): Date | null {
  if (!raw) {
    return null;
  }
  const date = new Date(raw);
  if (Number.isNaN(date.getTime())) {
    return null;
  }
  return date.getTime() - Date.now() > EXPIRATION_SENTINEL_HORIZON_MS
    ? null
    : date;
}

function toOpenRouterInput(raw: OpenRouterModel): OpenRouterModelInput {
  return {
    id: raw.id,
    name: raw.name,
    createdAt: new Date(raw.created * MS_PER_SECOND),
    contextLength: raw.context_length,
    maxCompletionTokens: raw.top_provider?.max_completion_tokens ?? null,
    promptCostPerToken: raw.pricing.prompt,
    completionCostPerToken: raw.pricing.completion,
    cacheReadCostPerToken: raw.pricing.input_cache_read ?? null,
    cacheWriteCostPerToken: raw.pricing.input_cache_write ?? null,
    expirationDate: toExpirationDate(raw.expiration_date),
    inputModalities: raw.architecture?.input_modalities ?? [],
    outputModalities: raw.architecture?.output_modalities ?? [],
    supportedParameters: raw.supported_parameters ?? [],
    reasoning: raw.reasoning
      ? {
          levels: (raw.reasoning.supported_efforts ?? []).filter((effort) =>
            REASONING_EFFORTS.includes(effort)
          ),
          mandatory: raw.reasoning.mandatory ?? false,
        }
      : null,
  };
}

function nextPageUrl(next: string | null | undefined): string | null {
  if (!next) {
    return null;
  }
  try {
    const url = new URL(next, OPENROUTER_MODELS_URL);
    return url.origin === OPENROUTER_ORIGIN ? url.toString() : null;
  } catch {
    return null;
  }
}

async function readOpenRouter(): Promise<OpenRouterRead> {
  const models: OpenRouterModelInput[] = [];
  const discarded: string[] = [];
  const fetched = new Set<string>();
  let nextUrl: string | null = OPENROUTER_MODELS_URL;
  let complete = true;

  while (nextUrl !== null) {
    if (fetched.size >= MAX_MODEL_PAGES || fetched.has(nextUrl)) {
      complete = false;
      break;
    }
    fetched.add(nextUrl);
    const page = openRouterPageSchema.parse(
      await getJson(nextUrl, 'OpenRouter models')
    );
    for (const raw of page.data) {
      const parsed = openRouterModelSchema.safeParse(raw);
      if (parsed.success) {
        models.push(toOpenRouterInput(parsed.data));
      } else {
        discarded.push(upstreamIdOf(raw));
      }
    }
    const nextLink = page.links?.next;
    nextUrl = nextPageUrl(nextLink);
    if (nextLink && nextUrl === null) {
      complete = false;
    }
  }

  if (discarded.length > 0) {
    console.warn(
      `OpenRouter: skipped ${discarded.length} unparseable models: ${discarded.join(', ')}`
    );
  }
  return { models, complete, discarded };
}

function servesProvider(
  catalog: ModelIndexCatalog,
  provider: (typeof INDEX_PROVIDERS)[number]
): boolean {
  return catalog.all().some((row) => {
    const pricing = catalog.getPricing(row.id);
    return (
      row.provider === provider &&
      catalog.isSupported(row.id) &&
      (pricing?.inputCostPerToken ?? 0) > 0 &&
      (pricing?.outputCostPerToken ?? 0) > 0 &&
      (row.maxInputTokens ?? 0) > 0
    );
  });
}

function snapshotRefusals(
  modelsDev: ModelsDevRead,
  openRouter: OpenRouterRead,
  catalog: ModelIndexCatalog
): string[] {
  const refusals: string[] = [];
  if (modelsDev.discarded.length > 0) {
    refusals.push(
      `models.dev discarded ${modelsDev.discarded.length} entries: ${modelsDev.discarded.join(', ')}`
    );
  }
  if (!openRouter.complete) {
    refusals.push('OpenRouter pagination stopped before the last page');
  }
  for (const provider of INDEX_PROVIDERS) {
    if (!servesProvider(catalog, provider)) {
      refusals.push(
        `${provider} has no supported, priced model with an input window`
      );
    }
  }
  return refusals;
}

function byId(a: IndexedModel, b: IndexedModel): number {
  if (a.id === b.id) {
    return 0;
  }
  return a.id < b.id ? -1 : 1;
}

function renderSnapshot(
  rows: readonly IndexedModel[],
  generatedAt: Date
): string {
  const body = [...rows]
    .sort(byId)
    .map((row) => `  ${JSON.stringify(row)},`)
    .join('\n');
  return [
    SNAPSHOT_HEADER,
    "import type { IndexedModel } from './indexed-model';",
    '',
    '/** The UTC day the snapshot was generated, `YYYY-MM-DD`. */',
    `export const MODEL_INDEX_SNAPSHOT_DATE = '${generatedAt.toISOString().slice(0, 10)}';`,
    '',
    'export const MODEL_INDEX_SNAPSHOT: readonly IndexedModel[] = [',
    body,
    '];',
    '',
  ].join('\n');
}

async function main(): Promise<void> {
  const [modelsDev, openRouter] = await Promise.all([
    readModelsDev(),
    readOpenRouter(),
  ]);
  const catalog = new ModelIndexCatalog([
    ...modelsDev.models,
    ...openRouter.models.map((model) =>
      fromOpenRouter(model, modelsDev.enrichment.get(model.id) ?? null)
    ),
  ]);

  const refusals = snapshotRefusals(modelsDev, openRouter, catalog);
  if (refusals.length > 0) {
    console.error('Refusing to write the model index snapshot:');
    for (const refusal of refusals) {
      console.error(`  ${refusal}`);
    }
    process.exitCode = 1;
    return;
  }

  const tempPath = `${SNAPSHOT_PATH}.tmp`;
  await writeFile(tempPath, renderSnapshot(catalog.all(), new Date()));
  await rename(tempPath, SNAPSHOT_PATH);
  const perProvider = INDEX_PROVIDERS.map(
    (provider) =>
      `${provider} ${catalog.all().filter((row) => row.provider === provider).length}`
  ).join(', ');
  console.log(
    `Wrote ${catalog.size} models (${perProvider}) to ${relative(process.cwd(), SNAPSHOT_PATH)}`
  );
}

main().catch((error: unknown) => {
  console.error('Snapshot refresh failed:', error);
  process.exitCode = 1;
});
